//! Authored/uncompiled/unrun. No synthetic object is adopted as native acceptance.
use super::*;
fn request()->Request {Request {schema:"aniflow.release-stages-request/v1".into(),source:MediaInput::AcceptedVideo {run_directory:"/synthetic/absent".into(),artifact_id:"master".into()},source_sha256:"a".repeat(64),stages:ORDER.into_iter().map(|stage|Intent {stage,mode:if stage.optional(){Mode::Disabled}else{Mode::Automated},selection:None,disabled_reason:stage.optional().then(||"Explicitly omitted for this release".into())}).collect()}}
#[test] fn stage_membership_and_order_are_closed(){let mut value=request();assert!(value.validate().is_ok());value.stages.swap(1,2);assert!(value.validate().is_err());value=request();value.stages.pop();assert!(value.validate().is_err());}
#[test] fn required_stages_cannot_be_skipped_or_satisfied_by_disabled_rows(){let mut value=request();value.stages[0].mode=Mode::Disabled;value.stages[0].disabled_reason=Some("Skip inspection".into());assert!(value.validate().is_err());value=request();value.stages[6].mode=Mode::Disabled;value.stages[6].disabled_reason=Some("Skip package review".into());assert!(value.validate().is_err());}
#[test] fn disabled_optional_requires_reason_and_no_hidden_selection(){let mut value=request();value.stages[1].disabled_reason=None;assert!(value.validate().is_err());value=request();value.stages[8].selection=Some(Selection::ExactBytes {directory:"/private/ignored".into(),manifest_sha256:"b".repeat(64)});assert!(value.validate().is_err());}
#[test] fn hook_is_configuration_intent_and_cannot_own_another_domains_evidence(){let mut value=request();value.stages[9].mode=Mode::Automated;value.stages[9].disabled_reason=None;assert!(value.validate().is_ok());value.stages[9].selection=Some(Selection::ExactBytes {directory:"/synthetic/absent".into(),manifest_sha256:"b".repeat(64)});assert!(value.validate().is_err());}
#[test] fn raw_manual_file_or_unknown_authority_cannot_replace_native_source(){let mut value=serde_json::to_value(request()).unwrap();value["source"]=serde_json::json!({"kind":"declared_file","file":"/private/loose.mp4","sha256":"a".repeat(64)});assert!(Request::from_json_slice(&serde_json::to_vec(&value).unwrap()).is_err());value=serde_json::to_value(request()).unwrap();value["automatic_approval"]=serde_json::json!(true);assert!(Request::from_json_slice(&serde_json::to_vec(&value).unwrap()).is_err());}
#[test] fn normal_status_needs_current_native_acceptance_not_saved_digest(){assert!(observe(&request(),&CancellationToken::new()).is_err());}
#[test] fn cancelled_observation_never_reaches_source_or_selected_owners(){let token=CancellationToken::new();token.cancel();assert!(observe(&request(),&token).is_err());}
#[test] fn exact_manual_review_states_remain_distinct(){assert_eq!(manual_state(ManualState::AwaitingInput),State::AwaitingInput);assert_eq!(manual_state(ManualState::AwaitingReview),State::AwaitingReview);assert_eq!(manual_state(ManualState::Rejected),State::Rejected);assert_eq!(manual_state(ManualState::Invalidated),State::Invalidated);assert_eq!(manual_state(ManualState::Approved),State::Complete);}
